export function aigcPublicError(error){if(error?.status===409&&String(error.message||'').startsWith('检测费用已更新'))return '检测费用已更新，请刷新页面后重新提交；尚未扣费。';if(error?.status===402)return '可用积分或对应套餐次数不足，请核对页面显示的本次费用并补充后重试。';if(error?.publicMessage)return error.publicMessage;if(error?.status===401)return '登录状态已失效，请登录后读取原任务。';if(error?.status===403)return '账户或访问权限已变化，请重新进入此功能。';if(error?.status===429)return '当前鉴别额度已用完或请求较多，请稍后再试。';if(error?.status===413)return '正文超过服务上限，请分章节提交。';if(error?.status===409)return '原任务与当前资料不一致，请先读取原任务，再重新确认。';if(error?.status===400||error?.status===422)return '请检查正文长度与处理授权后重试。';if(error?.status===404)return '暂未找到此账户的任务，请刷新最近任务。';return '鉴别服务暂未完成请求，请读取原任务状态，避免重复提交。';}
// Only explicitly recognized server outcomes may be shown to users. Unknown
// errors can contain provider details, so they receive a neutral fallback.
const AIGC_FAILURE_REASONS=new Map([
 ['部分正文未取得有效鉴别结论，已保留分段记录，本次未结算。','部分正文未获得有效检测结果，建议检查文稿内容后重新检测。'],
 ['正文未取得有效鉴别结论，已保留分段记录，本次未结算。','正文未获得有效检测结果，建议检查文稿内容后重新检测。'],
 ['文本鉴别暂未完成，已保留处理记录，不会自动重复提交。','检测服务暂时未能完成处理，请稍后重新检测。'],
 ['本次文本鉴别暂未完成，已保留记录，不会自动重复提交。','检测等待时间过长，请稍后重新检测。'],
 ['此文本鉴别未完成确认，为避免重复调用不会自动重新提交，请联系支持。','检测未能完成，请联系支持核查后重新检测。'],
 ['服务切换中断了本次鉴别，套餐预占次数已释放；不会自动重复提交。','服务切换导致本次检测中断，请稍后重新检测。'],
 ['已取消本次鉴别，套餐预占次数已释放。','本次检测已取消。'],
 ['本次检测费用预占已失效，未继续调用检测。','本次检测的费用预占已失效，请重新检测。']
]);
export function aigcFailureReason(reason){return AIGC_FAILURE_REASONS.get(reason)||'检测服务暂时未能完成处理，请稍后重新检测。';}
export function normalizeAigcResult(value){if(!value||!/^[-\w]{1,100}$/.test(String(value.id||''))||!['running','completed','failed'].includes(value.status))throw Error('invalid detection result');const whole=number=>Number.isInteger(number)&&number>=0?number:0,parts=(Array.isArray(value.parts)?value.parts:[]).slice(0,MAX_AIGC_PARTS).map((part,index)=>{const label=['aigc','ugc','undetermined'].includes(part.label)?part.label:'undetermined',confidence=label!=='undetermined'&&typeof part.confidence==='number'&&Number.isFinite(part.confidence)&&part.confidence>=0&&part.confidence<=100?part.confidence:null;return {...(Number.isSafeInteger(part.paragraphNumber)&&part.paragraphNumber>0?{paragraphNumber:part.paragraphNumber}:{}),...(Number.isSafeInteger(part.effectiveCharacters)&&part.effectiveCharacters>=0&&part.effectiveCharacters<=whole(part.characters)?{effectiveCharacters:part.effectiveCharacters}:{}),index:whole(part.index??index),start:whole(part.start),end:whole(part.end),characters:whole(part.characters),...(part.skipped===true&&label==='undetermined'&&confidence===null?{skipped:true,...(['whitespace','non_text'].includes(part.skipReason)?{skipReason:part.skipReason}:{})}:{}),label:confidence===null?'undetermined':label,confidence};});const counts={aigc:0,ugc:0,undetermined:0};parts.forEach(part=>{if(part.skipped!==true)counts[part.label]++;});const partCount=whole(value.partCount),completedParts=whole(value.completedParts),fullyCompleted=value.status==='completed'&&partCount>0&&parts.length===partCount&&completedParts===partCount;let verdict='undetermined';if(fullyCompleted&&value.conclusive!==false&&value.verdict!=='undetermined'&&!counts.undetermined&&(counts.aigc>0||counts.ugc>0)){verdict=counts.aigc&&counts.ugc?'mixed':counts.aigc?'aigc':'ugc';}const date=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T/.test(value)&&Number.isFinite(Date.parse(value))?new Date(value).toISOString():'';return {id:value.id,analysisVersion:value.analysisVersion===AIGC_PARAGRAPH_VERSION?AIGC_PARAGRAPH_VERSION:'length-v1',title:typeof value.title==='string'?value.title.slice(0,200):'',reportAvailable:value.reportAvailable===true,reportReady:value.reportReady===true,status:value.status,...(value.status==='failed'?{failureReason:aigcFailureReason(value.error)}:{}),partialResult:value.status==='completed'&&(value.error==='部分正文暂无法判定，已展示可用结果，本次未扣费。'||value.partialResult===true),characters:whole(value.characters),partCount,completedParts,parts,counts,verdict,fullyCompleted,createdAt:date(value.createdAt),updatedAt:date(value.updatedAt)};}

// A character-weighted coverage of actual chunk labels, never a conversion of
// provider confidence into authorship probability or a sentence-level AI rate.
export function aigcLabelCoverage(value){
 const item=normalizeAigcResult(value);let offset=0,aiCharacters=0,humanCharacters=0,unknownCharacters=0;
 const valid=item.fullyCompleted&&item.parts.every((part,index)=>{const ok=part.index===index&&part.start===offset&&part.end>part.start&&part.end<=item.characters&&part.characters===part.end-part.start;offset=part.end;if(!part.skipped){const weight=item.analysisVersion===AIGC_PARAGRAPH_VERSION?(part.effectiveCharacters??part.characters):part.characters;if(part.label==='aigc')aiCharacters+=weight;else if(part.label==='ugc')humanCharacters+=weight;else unknownCharacters+=weight;}return ok;})&&offset===item.characters;
 const testedCharacters=aiCharacters+humanCharacters+unknownCharacters,available=Boolean(valid&&item.verdict!=='undetermined'&&unknownCharacters===0&&testedCharacters>0);
 const judgedCharacters=aiCharacters+humanCharacters,partialAvailable=Boolean(valid&&unknownCharacters>0&&judgedCharacters>0&&testedCharacters>0);
 return {available,ratio:available?aiCharacters/testedCharacters:null,partialAvailable,partialRatio:partialAvailable?aiCharacters/judgedCharacters:null,coverageRatio:partialAvailable?judgedCharacters/testedCharacters:null,judgedCharacters,aiCharacters,humanCharacters,unknownCharacters,testedCharacters};
}
